    int need1 = 0;

    if (H % 2) need2 += W / 2;
    if (W % 2) need2 += H / 2;
    if ((H % 2) && (W % 2)) need1 = 1;

    int rem2 = 0, rem1 = 0;

    for (int i = 0; i < 26; i++) {
        int use4 = cnt[i] / 4;
        int take4 = (use4 < need4) ? use4 : need4;
        cnt[i] -= take4 * 4;
        need4 -= take4;
    }

    if (need4 > 0) {
        printf("No\n");
        return 0;
    }

    for (int i = 0; i < 26; i++) {
