            pairs = W / 2;
        } else if (W % 2 == 1) {
            pairs = H / 2;
        }
        int center = (H % 2 == 1 && W % 2 == 1) ? 1 : 0;

        // Use counts to fill fours
        for (int i = 0; i < 26; i++) {
            while (cnt[i] >= 4 && fours > 0) {
