public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();

        int[] cnt = new int[26];
        for (int i = 0; i < H; i++) {
            String s = fs.next();
            for (int j = 0; j < W; j++) {
                cnt[s.charAt(j) - 'a']++;
            }
        }

        int need4 = (H / 2) * (W / 2);
        int need2 = 0;
        int need1 = 0;

        if (H % 2 == 1) need2 += W / 2;
        if (W % 2 == 1) need2 += H / 2;
        if (H % 2 == 1 && W % 2 == 1) need1 = 1;

        // First use groups of 4 for 2x2 symmetric blocks.
        for (int i = 0; i < 26; i++) {
            int use = Math.min(cnt[i] / 4, need4);
            cnt[i] -= use * 4;
            need4 -= use;
        }

        if (need4 > 0) {
            System.out.println("No");
            return;
        }

        // Then use pairs for the middle row / middle column if needed.
        for (int i = 0; i < 26; i++) {
            int use = Math.min(cnt[i] / 2, need2);
            cnt[i] -= use * 2;
            need2 -= use;
        }

        if (need2 > 0) {
            System.out.println("No");
            return;
        }

        // Finally, if both H and W are odd, exactly one single character is needed.
        int singles = 0;
        for (int i = 0; i < 26; i++) singles += cnt[i];

        if (singles == need1) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

