        for (char c : s) cnt[c - 'a']++;
    }

    int odd = 0, mod2 = 0;
    for (int x : cnt) {
        if (x % 2) odd++;
        if (x % 4 == 2) mod2++;
    }

    bool ok = false;

    if (H % 2 == 0 && W % 2 == 0) {
        // All cells must be grouped in 4s
        ok = (odd == 0 && mod2 == 0);
    } else if (H % 2 == 1 && W % 2 == 1) {
        // One center cell, and (H/2 + W/2) pairs on the middle row/column
        int needPairs = H / 2 + W / 2;
        ok = (odd == 1);

        if (ok) {
            int pairsAvailable = 0;
            for (int x : cnt) pairsAvailable += (x % 4) / 2;
            ok = (pairsAvailable <= needPairs);
        }
    } else {
        // Exactly one of H, W is odd
        int needPairs = (H % 2 ? W / 2 : H / 2);
        ok = (odd == 0);

        if (ok) {
            int pairsAvailable = 0;
            for (int x : cnt) pairsAvailable += (x % 4) / 2;
            ok = (pairsAvailable <= needPairs);
        }
    }

    cout << (ok ? "Yes" : "No") << '\n';
